<template>
  <section class="scientific-conditions" aria-label="蒸散发与起算条件"><h3>蒸散发与起算条件</h3><p v-if="error" class="error" role="alert">{{ error }} <button class="btn" @click="load">重试读取</button></p><p v-if="loading">正在读取实际起算条件…</p><fieldset v-else-if="settings" :disabled="disabled"><div class="condition-fields"><label>起算方式<select v-model="settings.statePolicy.strategy" class="input" @change="changed"><option value="independent-warmup">{{ continuous ? '各期独立预热' : '分场预热' }}</option><option v-if="continuous" value="continuous-origin">连续演算</option></select></label><label>预热天数<input v-model.number="days" class="input" type="number" min="0" max="365" step="1" @change="changed" /></label><label>蒸散发估计输入<select v-model="mode" class="input" @change="changeMode"><option value="monthly-climatology-assumption">经验月值</option><option value="constant-assumption">固定小时值</option><option v-if="inheritedHourly" value="inherited-hourly">原逐时输入（沿用）</option></select></label><label v-if="mode==='constant-assumption'">每小时输入（mm/h）<input v-model.number="fixed" class="input" type="number" min="0" step="0.01" @change="changed" /></label></div><p class="condition-note">输入为蒸散发需求估计值，实际蒸散发由模型计算；固定值可设为0。</p><div v-if="mode==='monthly-climatology-assumption'" class="monthly-values"><label v-for="(_,index) in monthly" :key="index">{{ index+1 }}月 · mm/日<input v-model.number="monthly[index]" class="input" type="number" min="0" step="0.1" :aria-label="`${index+1}月蒸散发日值`" @change="changed" /><small>{{ Number.isFinite(monthly[index]) ? (monthly[index]/24).toFixed(3) : '—' }} mm/h</small></label></div></fieldset></section>
</template>
<script setup>
import { ref, watch } from 'vue'
import { modelApi } from '@/services/modelBackendService'
const props=defineProps({modelValue:Object,scienceVersionId:String,disabled:Boolean,statePolicy:String,warmupDays:Number,continuous:Boolean})
const emit=defineEmits(['update:modelValue'])
const settings=ref(null),days=ref(7),mode=ref('monthly-climatology-assumption'),monthly=ref([3,3,3.5,4,4.5,5,5.5,5.5,4.5,3.5,3,3]),fixed=ref(0),loading=ref(false),error=ref(''),inheritedHourly=ref(false)
let sequence=0
async function load(){const token=++sequence;loading.value=true;error.value='';try{const source=props.modelValue||await modelApi('science-conditions'+(props.scienceVersionId?'?versionId='+encodeURIComponent(props.scienceVersionId):''));if(token!==sequence)return;settings.value=JSON.parse(JSON.stringify(source));settings.value.statePolicy={strategy:props.statePolicy||source.statePolicy.strategy,warmupHours:Math.round((props.warmupDays??7)*24)};days.value=settings.value.statePolicy.warmupHours/24;mode.value=source.evaporation.mode;inheritedHourly.value=mode.value==='inherited-hourly';if(source.evaporation.monthlyValuesMmPerDay)monthly.value=[...source.evaporation.monthlyValuesMmPerDay];if(source.evaporation.valueMmPerHour!=null)fixed.value=source.evaporation.valueMmPerHour}catch(failure){if(token===sequence)error.value=failure.message}finally{if(token===sequence)loading.value=false}}
function changed(){if(!props.continuous)settings.value.statePolicy.strategy='independent-warmup';settings.value.statePolicy.warmupHours=Number(days.value)*24;settings.value.evaporation=mode.value==='constant-assumption'?{mode:mode.value,valueMmPerHour:fixed.value}:mode.value==='monthly-climatology-assumption'?{mode:mode.value,monthlyValuesMmPerDay:[...monthly.value]}:{mode:'inherited-hourly'};emit('update:modelValue',{evaporation:JSON.parse(JSON.stringify(settings.value.evaporation)),statePolicy:{...settings.value.statePolicy}})}
function changeMode(){changed()}
watch(()=>[props.scienceVersionId,props.statePolicy,props.warmupDays,props.modelValue,props.continuous],load,{immediate:true})
</script>
<style scoped>
.scientific-conditions{border-top:1px solid #dce6e1;padding-top:18px;margin-top:20px}.scientific-conditions h3{font-size:16px;margin:0 0 16px}.scientific-conditions fieldset{border:0;padding:0;margin:0}.condition-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.scientific-conditions label{display:grid;gap:8px;font-size:14px}.scientific-conditions .input{width:100%;min-height:36px;font-size:14px}.condition-note{font-size:14px;color:#71877e;line-height:1.7}.monthly-values{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-top:16px}.monthly-values small{font-size:13px;color:#6e8479}.error{color:#a74737;font-size:14px}@media(max-width:700px){.monthly-values{grid-template-columns:repeat(3,minmax(0,1fr))}}
</style>
